#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my @all_go_files;
find(
    sub {
        return unless -f && $_ =~ /\.go$/;
        return if $_ =~ /_test\.go$/;
        push @all_go_files, $File::Find::name;
    },
    $ROOT
);

my %internal_defs;
my %file_info;

sub strip_comments {
    my ($code) = @_;
    $code =~ s/\/\*.*?\*//gs;
    $code =~ s/\/\/.*$//mg;
    return $code;
}

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return;
    my $raw = do { local $/; <$fh> };
    close $fh;

    my $code = strip_comments($raw);

    my ($pkg) = $code =~ /^\s*package\s+(\w+)/m;
    $pkg //= 'main';

    my $rel = $path;
    $rel =~ s/^\Q$ROOT\E\/?//;
    my $dir = dirname($rel);
    $dir =~ s/\\/\//g;
    my $pkgpath = ($dir eq '.') ? $MODULE : "$MODULE/$dir";

    my %imports;
    while ($code =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1;
        if (defined $block) {
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $imp) = ($1, $2);
                $alias //= basename($imp);
                $imports{$alias} = $imp;
            }
        } else {
            my $imp = $2;
            $imports{basename($imp)} = $imp;
        }
    }

    my @defs;
    my $raw_nocomment = strip_comments($raw);
    while ($raw_nocomment =~ /^(\s*)func\s+(?:(\([^)]*\)\s+)?(\w+))\s*\(/mg) {
        my $pos = pos($raw_nocomment) - length($0);
        my $line = 1 + substr($raw_nocomment, 0, $pos) =~ tr/\n//;
        my $recv_raw = $2;
        my $name = $3;
        my $recv = '';
        if (defined $recv_raw) {
            if ($recv_raw =~ /\*\s*(\w+)/) {
                $recv = '*' . $1;
            } elsif ($recv_raw =~ /(\w+)\s*$/) {
                $recv = $1;
            }
        }
        push @defs, { name => $name, recv => $recv, line => $line };
    }

    $file_info{$path} = {
        pkg     => $pkg,
        pkgpath => $pkgpath,
        imports => \%imports,
        defs    => \@defs,
        raw     => $raw,
        code    => $code,
    };

    if ($path =~ /\/internal\//) {
        for my $d (@defs) {
            my $key = "$pkgpath|$d->{recv}|$d->{name}";
            $internal_defs{$key} = {
                path  => $path,
                line  => $d->{line},
                pkg   => $pkg,
                pkgpath => $pkgpath,
                recv  => $d->{recv},
                name  => $d->{name},
            };
        }
    }
}

for my $f (@all_go_files) {
    parse_go_file($f);
}

my %by_pkgpath_name;
for my $key (keys %internal_defs) {
    my $d = $internal_defs{$key};
    push @{$by_pkgpath_name{"$d->{pkgpath}|$d->{name}"}}, $key;
}

my %import_to_pkgpath;
for my $path (keys %file_info) {
    my $fi = $file_info{$path};
    for my $alias (keys %{$fi->{imports}}) {
        my $imp = $fi->{imports}{$alias};
        if ($imp =~ /\/internal\// || $imp eq "$MODULE/internal" || $imp =~ /^\Q$MODULE\E\/internal/) {
            $import_to_pkgpath{"$path|$alias"} = $imp;
        }
    }
}

my %fanin;

sub add_call {
    my ($def_key, $caller_path, $caller_func, $line) = @_;
    my $caller_id = "$caller_path:$caller_func";
    $fanin{$def_key}{callers}{$caller_id} = 1;
    $fanin{$def_key}{sites}++;
    $fanin{$def_key}{caller_details}{$caller_id} = "$caller_path:$line in $caller_func";
}

sub current_func_at_line {
    my ($defs, $line) = @_;
    my $current = '<top>';
    for my $d (@$defs) {
        if ($d->{line} <= $line) {
            my $fn = $d->{name};
            if ($d->{recv}) {
                $fn = "$d->{recv}.$fn";
            }
            $current = $fn;
        }
    }
    return $current;
}

for my $path (keys %file_info) {
    my $fi = $file_info{$path};
    my $raw_nc = strip_comments($fi->{raw});
    my @lines = split /\n/, $raw_nc;

    for my $line_num (0 .. $#lines) {
        my $line = $lines[$line_num];
        my $ln = $line_num + 1;
        my $caller_func = current_func_at_line($fi->{defs}, $ln);

        if ($line =~ /^\s*func\s+/) {
            next;
        }

        while ($line =~ /(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
            my ($alias, $fname) = ($1, $2);
            next if $fname eq 'go' || $fname eq 'defer' || $fname eq 'new';

            my $imp_key = "$path|$alias";
            if (exists $import_to_pkgpath{$imp_key}) {
                my $pkgpath = $import_to_pkgpath{$imp_key};
                for my $key (@{$by_pkgpath_name{"$pkgpath|$fname"} // []}) {
                    my $def = $internal_defs{$key};
                    if ($path eq $def->{path} && $ln == $def->{line}) {
                        next;
                    }
                    add_call($key, $path, $caller_func, $ln);
                }
            }
            if ($path =~ /\/internal\//) {
                my $pkgpath = $fi->{pkgpath};
                for my $key (@{$by_pkgpath_name{"$pkgpath|$fname"} // []}) {
                    my $def = $internal_defs{$key};
                    if ($alias eq $fi->{pkg}) {
                        if ($path eq $def->{path} && $ln == $def->{line}) {
                            next;
                        }
                        add_call($key, $path, $caller_func, $ln);
                    }
                }
            }
        }

        while ($line =~ /(?<![\w.])(\w+)\s*\(/g) {
            my $fname = $1;
            next if $fname =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|print|println|close|complex|real|imag|map|struct|interface|chan|range|case|default|select|else|const|var|type|import|package)$/;

            if ($path =~ /\/internal\//) {
                my $pkgpath = $fi->{pkgpath};
                for my $key (@{$by_pkgpath_name{"$pkgpath|$fname"} // []}) {
                    my $def = $internal_defs{$key};
                    if ($path eq $def->{path} && $ln == $def->{line}) {
                        next;
                    }
                    add_call($key, $path, $caller_func, $ln);
                }
            }
        }
    }
}

my @ranked = sort {
    (scalar(keys %{$fanin{$b}{callers} // {}})) <=> (scalar(keys %{$fanin{$a}{callers} // {}}))
    || (($fanin{$b}{sites} // 0) <=> ($fanin{$a}{sites} // 0))
} keys %fanin;

print "TOP 30 by distinct caller functions:\n";
for my $i (0 .. 29) {
    last unless defined $ranked[$i];
    my $key = $ranked[$i];
    my $d = $internal_defs{$key};
    my $callers = scalar(keys %{$fanin{$key}{callers}});
    my $sites = $fanin{$key}{sites};
    my $sym = $d->{recv} ? "$d->{recv}.$d->{name}" : $d->{name};
    print sprintf("%3d callers, %3d sites | %s | %s | %s\n",
        $callers, $sites, $sym, $d->{path}, $d->{pkgpath});
}

print "\nTotal internal definitions: " . scalar(keys %internal_defs) . "\n";

if (@ranked) {
    my $key = $ranked[0];
    print "\n=== TOP SYMBOL DETAIL ===\n";
    for my $c (sort keys %{$fanin{$key}{caller_details}}) {
        print "  $fanin{$key}{caller_details}{$c}\n";
    }
}

