            if ($path =~ /\/internal\//) {
                my $pkgpath = $fi->{pkgpath};
                for my $key (@{$by_pkgpath_name{"$pkgpath|$fname"} // []}) {
                    my $def = $internal_defs{$key};
                    if ($path eq $def->{path} && $ln == $def->{line}) {
                        next;
                    }
                    add_call($key, $path, $caller_func, $ln);
                }
            }
        }
    }
}

my @ranked = sort {
    (scalar(keys %{$fanin{$b}{callers} // {}})) <=> (scalar(keys %{$fanin{$a}{callers} // {}}))
    || (($fanin{$b}{sites} // 0) <=> ($fanin{$a}{sites} // 0))
} keys %fanin;

print "TOP 30 by distinct caller functions:\n";
for my $i (0 .. 29) {
    last unless defined $ranked[$i];
    my $key = $ranked[$i];
    my $d = $internal_defs{$key};
    my $callers = scalar(keys %{$fanin{$key}{callers}});
    my $sites = $fanin{$key}{sites};
    my $sym = $d->{recv} ? "$d->{recv}.$d->{name}" : $d->{name};
    print sprintf("%3d callers, %3d sites | %s | %s | %s\n",
        $callers, $sites, $sym, $d->{path}, $d->{pkgpath});
}

print "\nTotal internal definitions: " . scalar(keys %internal_defs) . "\n";

if (@ranked) {
    my $key = $ranked[0];
    print "\n=== TOP SYMBOL DETAIL ===\n";
    for my $c (sort keys %{$fanin{$key}{caller_details}}) {
        print "  $fanin{$key}{caller_details}{$c}\n";
    }
}

