#!/bin/bash
ROOT=/bench/repo
MODULE=github.com/usememos/memos

# Collect go files (non-test)
mapfile -t ALL_GO < <(find "$ROOT" -name '*.go' ! -name '*_test.go' | sort)

strip_comments() {
  perl -pe 's/\/\*.*?\*//gs; s/\/\/.*$//g' "$1"
}

# Parse all files -> temp data
DEFS_FILE=/tmp/go_defs.txt
CALLS_FILE=/tmp/go_calls.txt
IMPORTS_FILE=/tmp/go_imports.txt
FILEPKG_FILE=/tmp/go_filepkg.txt
: > "$DEFS_FILE"
: > "$CALLS_FILE"
: > "$IMPORTS_FILE"
: > "$FILEPKG_FILE"

for f in "${ALL_GO[@]}"; do
  rel="${f#$ROOT/}"
  dir=$(dirname "$rel")
  if [ "$dir" = "." ]; then pkgpath="$MODULE"; else pkgpath="$MODULE/$dir"; fi

  raw_nc=$(strip_comments "$f")
  pkg=$(echo "$raw_nc" | head -50 | grep -oP '^\s*package\s+\K\w+' | head -1)
  [ -z "$pkg" ] && pkg=main
  echo "$f|$pkg|$pkgpath" >> "$FILEPKG_FILE"

  # imports
  imp_block=$(echo "$raw_nc" | perl -0777 -ne 'while(/import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g){if($1){print $1}else{print "\"$2\"\n"}}')
  echo "$imp_block" | while read -r line; do
    [ -z "$line" ] && continue
  done
  echo "$raw_nc" | perl -0777 -ne '
    while(/import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
      if($1) {
        while($1 =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
          my ($a,$p)=($1,$2); $a=$a//do{($p=~m{/([^/]+)$})?$1:$p}; 
          print "'"$f"'|$a|$p\n";
        }
      } else {
        my $p=$2; my $a=($p=~m{/([^/]+)$})?$1:$p;
        print "'"$f"'|$a|$p\n";
      }
    }
  ' >> "$IMPORTS_FILE"

  # definitions with line numbers
  line_num=0
  while IFS= read -r line; do
    ((line_num++))
    if echo "$line" | grep -qP '^\s*func\s+'; then
      recv=""
      name=""
      if echo "$line" | grep -qP '^\s*func\s+\('; then
        # method
        recv=$(echo "$line" | perl -ne 'if(/func\s+\(\s*\*?\s*(\w+)/){print "*$1"} elsif(/func\s+\(\s*(\w+)/){print $1}')
        name=$(echo "$line" | perl -ne 'if(/func\s+\([^)]+\)\s+(\w+)/){print $1}')
      else
        name=$(echo "$line" | perl -ne 'if(/func\s+(\w+)/){print $1}')
      fi
      if [ -n "$name" ] && [[ "$f" == *"/internal/"* ]]; then
        echo "$pkgpath|$recv|$name|$f|$line_num" >> "$DEFS_FILE"
      fi
    fi
    # call sites on this line (skip func def lines)
    if ! echo "$line" | grep -qP '^\s*func\s+'; then
      # qualified calls
      echo "$line" | perl -ne '
        while(/(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
          print "'"$f"'|'$line_num'|qualified|$1|$2\n";
        }
      ' >> "$CALLS_FILE"
      # unqualified
      echo "$line" | perl -ne '
        while(/(?<![\w.])(\w+)\s*\(/g) {
          my $w=$1;
          next if $w =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|print|println|close|complex|real|imag|map|struct|interface|chan|range|case|default|select|else|const|var|type|import|package)$/;
          print "'"$f"'|'$line_num'|unqualified||$w\n";
        }
      ' >> "$CALLS_FILE"
    fi
  done < <(strip_comments "$f")
done

echo "Defs: $(wc -l < "$DEFS_FILE")"
echo "Calls: $(wc -l < "$CALLS_FILE")"
echo "Imports: $(wc -l < "$IMPORTS_FILE")"

# Build fan-in counts using awk
awk -F'|' '
BEGIN { OFS="|" }
FNR==NR && FILENAME ~ /go_filepkg/ {
  filepkg[$1]=$2; filepath[$1]=$3; next
}
FNR==NR && FILENAME ~ /go_imports/ {
  if ($3 ~ /\/internal\// || $3 == "github.com/usememos/memos/internal") {
    importmap[$1 "|" $2]=$3
  }
  next
}
FNR==NR && FILENAME ~ /go_defs/ {
  key=$1"|"$2"|"$3
  defpath[key]=$4
  defline[key]=$5
  pkgname[key]=$1
  defname[key]=$3
  defrecv[key]=$2
  by_pkgname[$1"|"$3]=by_pkgname[$1"|"$3] key ";"
  next
}
{
  # calls file
  callfile=$1; callline=$2; calltype=$3; alias=$4; fname=$5
  pkgpath=filepath[callfile]
  pkg=filepkg[callfile]

  if (calltype == "qualified") {
  # via import
    imp=importmap[callfile "|" alias]
    if (imp != "") {
      keys=by_pkgname[imp "|" fname]
      n=split(keys, ka, ";")
      for (i=1;i<=n;i++) {
        if (ka[i]=="") continue
        key=ka[i]
        if (callfile == defpath[key] && callline == defline[key]) continue
        fanin[key,callfile]++
        sites[key]++
      }
    }
    # same package qualified
    if (alias == pkg && callfile ~ /\/internal\//) {
      keys=by_pkgname[pkgpath "|" fname]
      n=split(keys, ka, ";")
      for (i=1;i<=n;i++) {
        if (ka[i]=="") continue
        key=ka[i]
        if (callfile == defpath[key] && callline == defline[key]) continue
        fanin[key,callfile]++
        sites[key]++
      }
    }
  } else {
    # unqualified - same package internal only
    if (callfile ~ /\/internal\//) {
      keys=by_pkgname[pkgpath "|" fname]
      n=split(keys, ka, ";")
      for (i=1;i<=n;i++) {
        if (ka[i]=="") continue
        key=ka[i]
        if (callfile == defpath[key] && callline == defline[key]) continue
        fanin[key,callfile]++
        sites[key]++
      }
    }
  }
}
END {
  for (k in fanin) {
    split(k, parts, SUBSEP)
    key=parts[1]
    callers[key]++
  }
  PROCEDURE sorted[1000]
  n=0
  for (key in callers) {
    sorted[n]=key
    n++
  }
  # simple sort by callers desc
  for (i=0;i<n;i++) {
    for (j=i+1;j<n;j++) {
      if (callers[sorted[j]] > callers[sorted[i]]) {
        t=sorted[i]; sorted[i]=sorted[j]; sorted[j]=t
      }
    }
  }
  print "TOP 30:"
  for (i=0;i<30 && i<n;i++) {
    key=sorted[i]
    sym=defrecv[key]
    if (sym != "") sym=sym "." defname[key]
    else sym=defname[key]
    print callers[key], sites[key], sym, defpath[key], key
  }
}
' "$FILEPKG_FILE" "$IMPORTS_FILE" "$DEFS_FILE" "$CALLS_FILE"

