#!/usr/bin/awk -f
# fanin.awk - compute fan-in for internal/ Go symbols
BEGIN {
  ROOT = "/bench/repo"
  MODULE = "github.com/usememos/memos"
}

function strip_comments(str,    tmp) {
  gsub(/\/\*([^*]|\*+[^*/])*\*+\//, "", str)
  gsub(/\/\/.*$/, "", str)
  return str
}

function basename(path,    n, parts) {
  n = split(path, parts, "/")
  return parts[n]
}

function pkgpath_from_file(f,    rel, dir) {
  sub("^" ROOT "/?", "", f)
  dir = f
  sub("/[^/]+$", "", dir)
  if (dir == f || dir == "") return MODULE
  return MODULE "/" dir
}

# Process definition or call extraction from a file
function process_file(f,    raw, nc, pkg, pp, line, nlines, i, line, recv, name, alias, fname, key, imp) {
  # read file
  while ((getline line < f) > 0) raw = raw line "\n"
  close(f)
  nc = strip_comments(raw)

  pkg = ""
  if (match(nc, /package[ \t]+([A-Za-z_][A-Za-z0-9_]*)/)) pkg = substr(nc, RSTART+8, RLENGTH-8)
  # fix pkg extraction
  if (match(nc, /^[ \t]*package[ \t]+([A-Za-z_][A-Za-z0-9_]*)/)) {
    pkg = substr(nc, RSTART, RLENGTH)
    sub(/^[ \t]*package[ \t]+/, "", pkg)
  }

  pp = pkgpath_from_file(f)
  file_pkg[f] = pkg
  file_pp[f] = pp

  # imports
  pos = 1
  while (match(nc, /import[ \t]*\(/, pos)) {
    start = RSTART + RLENGTH
    depth = 1
    i = start
    block = ""
    while (i <= length(nc) && depth > 0) {
      c = substr(nc, i, 1)
      if (c == "(") depth++
      else if (c == ")") depth--
      if (depth > 0) block = block c
      i++
    }
    pos = i
    # parse block lines
    n = split(block, blines, "\n")
    for (j = 1; j <= n; j++) {
      bl = blines[j]
      alias = basename(bl)
      sub(/^[^"]*"/, "", bl)
      sub(/".*$/, "", bl)
      imp = bl
      if (match(blines[j], /([A-Za-z_][A-Za-z0-9_]*)[ \t]+"/)) {
        alias = substr(blines[j], RSTART, RLENGTH)
        sub(/[ \t]+".*$/, "", alias)
      }
      if (imp ~ /\/internal\//) import_map[f SUBSEP alias] = imp
    }
  }
  # single import
  pos = 1
  while (match(nc, /import[ \t]+"([^"]+)"/, pos)) {
    imp = substr(nc, RSTART, RLENGTH)
    sub(/^import[ \t]+"/, "", imp)
    sub(/"$/, "", imp)
    alias = basename(imp)
    if (imp ~ /\/internal\//) import_map[f SUBSEP alias] = imp
    pos = RSTART + RLENGTH
  }

  # definitions and calls line by line
  nlines = split(nc, lines, "\n")
  for (i = 1; i <= nlines; i++) {
    line = lines[i]
    # definition
    if (match(line, /^[ \t]*func[ \t]+(\([^)]*\)[ \t]+)?([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/)) {
      name = substr(line, RSTART, RLENGTH)
      if (match(name, /^func[ \t]+\(/)) {
        recv = name
        sub(/^func[ \t]+\(/, "", recv)
        sub(/\).*$/, "", recv)
        gsub(/^[ \t\*]+/, "", recv)
        if (match(recv, /\*[ \t]*([A-Za-z_][A-Za-z0-9_]*)/)) recv = "*" substr(recv, RSTART, RLENGTH)
        else if (match(recv, /([A-Za-z_][A-Za-z0-9_]*)/)) recv = substr(recv, RSTART, RLENGTH)
        sub(/^func[ \t]+\([^)]+\)[ \t]+/, "", name)
        sub(/[ \t]*\(.*$/, "", name)
      } else {
        recv = ""
        sub(/^func[ \t]+/, "", name)
        sub(/[ \t]*\(.*$/, "", name)
      }
      if (f ~ /\/internal\//) {
        key = pp SUBSEP recv SUBSEP name
        def_file[key] = f
        def_line[key] = i
        def_pp[key] = pp
        def_recv[key] = recv
        def_name[key] = name
        idx = ppname_count[pp SUBSEP name]
        ppname_list[pp SUBSEP name, idx] = key
        ppname_count[pp SUBSEP name] = idx + 1
      }
      continue
    }

    # calls - qualified
    cline = line
    while (match(cline, /(^|[^A-Za-z0-9_.])([A-Za-z_][A-Za-z0-9_]*)[ \t]*\.[ \t]*([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/)) {
      alias = substr(cline, RSTART, RLENGTH)
      sub(/^[^A-Za-z0-9_.]/, "", alias)
      sub(/\.[ \t]*[A-Za-z_][A-Za-z0-9_]*[ \t]*\(.*$/, "", alias)
      fname = cline
      sub(/^.*\.[ \t]*/, "", fname)
      sub(/[ \t]*\(.*$/, "", fname)
      record_call(f, pkg, pp, alias, fname, i)
      cline = substr(cline, RSTART + 1)
    }
    # unqualified
    cline = line
    while (match(cline, /(^|[^A-Za-z0-9_.])([A-Za-z_][A-Za-z0-9_]*)[ \t]*\(/)) {
      fname = substr(cline, RSTART, RLENGTH)
      sub(/^[^A-Za-z0-9_.]/, "", fname)
      sub(/[ \t]*\(.*$/, "", fname)
