      sub(/^[^A-Za-z0-9_.]/, "", fname)
      sub(/[ \t]*\(.*$/, "", fname)
      if (fname ~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|print|println|close|complex|real|imag|map|struct|interface|chan|range|case|default|select|else|const|var|type|import|package)$/) {
        cline = substr(cline, RSTART + 1)
        continue
      }
      record_call(f, pkg, pp, "", fname, i)
      cline = substr(cline, RSTART + 1)
    }
  }
}

function record_call(f, pkg, pp, alias, fname,    imp, key, idx, n, k, caller) {
  # via import
  if (alias != "" && import_map[f SUBSEP alias] != "") {
    imp = import_map[f SUBSEP alias]
    n = ppname_count[imp SUBSEP fname]
    for (idx = 0; idx < n; idx++) {
      key = ppname_list[imp SUBSEP fname, idx]
      if (f == def_file[key] && i == def_line[key]) continue
      caller = f SUBSEP "<unknown>"
      fanin_caller[key SUBSEP f] = 1
      fanin_sites[key]++
    }
  }
  # same package qualified
  if (alias != "" && alias == pkg && f ~ /\/internal\//) {
    n = ppname_count[pp SUBSEP fname]
    for (idx = 0; idx < n; idx++) {
      key = ppname_list[pp SUBSEP fname, idx]
      if (f == def_file[key] && i == def_line[key]) continue
      fanin_caller[key SUBSEP f] = 1
      fanin_sites[key]++
    }
  }
  # unqualified same package
  if (alias == "" && f ~ /\/internal\//) {
    n = ppname_count[pp SUBSEP fname]
    for (idx = 0; idx < n; idx++) {
      key = ppname_list[pp SUBSEP fname, idx]
      if (f == def_file[key] && i == def_line[key]) continue
      fanin_caller[key SUBSEP f] = 1
      fanin_sites[key]++
    }
  }
  # unqualified won't work outside internal for unexported
  # exported from internal called unqualified from outside - rare, skip
  # qualified from outside via import - handled above
  if (alias == "" && f !~ /\/internal\//) {
    # try all internal packages with this exported name - too broad, skip
  }
}

END {
  # count callers per key
  for (fc in fanin_caller) {
  split(fc, p, SUBSEP)
  key = p[1] SUBSEP p[2] SUBSEP p[3]
  callers[key]++
  }
  # rank
  n = 0
  for (key in callers) {
    ranked[n] = key
    n++
  }
  for (i = 0; i < n; i++) {
    for (j = i+1; j < n; j++) {
      if (callers[ranked[j]] > callers[ranked[i]]) {
        t = ranked[i]; ranked[i] = ranked[j]; ranked[j] = t
      }
    }
  }
  print "Total defs:", n
  for (i = 0; i < 30 && i < n; i++) {
    key = ranked[i]
    sym = def_recv[key]
    if (sym != "") sym = sym "." def_name[key]
    else sym = def_name[key]
    print callers[key], fanin_sites[key], sym, def_file[key]
  }
}

