#!/usr/bin/perl
use strict;
use warnings;

my $ROOT = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

my @files = `find $ROOT -name '*.go' ! -name '*_test.go'`;
chomp @files;

sub strip_comments {
    my ($s) = @_;
    $s =~ s/\/\*.*?\*//gs;
    $s =~ s/\/\/.*$//mg;
    return $s;
}

sub basename {
    my ($p) = @_;
    $p =~ s{.*/}{};
    return $p;
}

sub pkgpath {
    my ($f) = @_;
    $f =~ s/^\Q$ROOT\E\/?//;
    my $d = $f;
    $d =~ s/\/[^\/]+$//;
    return ($d eq '' || $d eq $f) ? $MODULE : "$MODULE/$d";
}

my %file_pkg;
my %file_pp;
my %imports;      # "$f|$alias" => imp
my %defs;         # key => {path,line,recv,name}
my %ppname;       # "$pp|$name" => [keys]
my %fanin_files;  # key => {caller_file => 1}
my %fanin_sites;  # key => count

for my $f (@files) {
    open my $fh, '<', $f or next;
    my $raw = do { local $/; <$fh> };
    close $fh;
    my $nc = strip_comments($raw);

    my ($pkg) = $nc =~ /^\s*package\s+(\w+)/m;
    $pkg //= 'main';
    my $pp = pkgpath($f);
    $file_pkg{$f} = $pkg;
    $file_pp{$f} = $pp;

    while ($nc =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        if (defined $1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($a, $imp) = ($1, $2);
                $a = basename($imp) unless defined $a;
                if ($imp =~ /\/internal\//) {
                    $imports{"$f|$a"} = $imp;
                }
            }
        } else {
            my $imp = $2;
            my $a = basename($imp);
            if ($imp =~ /\/internal\//) {
                $imports{"$f|$a"} = $imp;
            }
        }
    }

    my @lines = split /\n/, $nc;
    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        my $ln = $i + 1;

        if ($line =~ /^\s*func\s+(?:(\([^)]*\)\s+)?(\w+))\s*\(/) {
            my $recv_raw = $1;
            my $name = $2;
            my $recv = '';
            if (defined $recv_raw) {
                if ($recv_raw =~ /\*\s*(\w+)/) { $recv = "*$1"; }
                elsif ($recv_raw =~ /(\w+)/) { $recv = $1; }
            }
            if ($f =~ /\/internal\//) {
                my $key = "$pp|$recv|$name";
                $defs{$key} = { path => $f, line => $ln, recv => $recv, name => $name, pp => $pp };
                push @{$ppname{"$pp|$name"}}, $key;
            }
            next;
        }

        # qualified calls
        while ($line =~ /(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
            my ($alias, $fname) = ($1, $2);
            resolve_call($f, $pkg, $pp, $alias, $fname, $ln, 1);
        }
        # unqualified
        while ($line =~ /(?<![\w.])(\w+)\s*\(/g) {
            my $fname = $1;
            next if $fname =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|print|println|close|complex|real|imag|map|struct|interface|chan|range|case|default|select|else|const|var|type|import|package)$/;
            resolve_call($f, $pkg, $pp, '', $fname, $ln, 0);
        }
    }
}

sub resolve_call {
    my ($f, $pkg, $pp, $alias, $fname, $ln, $qualified) = @_;
    my @targets;

    if ($qualified && $alias) {
        if (my $imp = $imports{"$f|$alias"}) {
