#!/usr/bin/perl
use strict;
use warnings;

my $ROOT = '/bench/repo';

# Build symbol table from internal defs
my %sym;  # name => [{recv, path, line, pkgpath}]
my @files = `find $ROOT/internal -name '*.go' ! -name '*_test.go'`;
chomp @files;

sub strip { my $s=shift; $s=~s/\/\*.*?\*//gs; $s=~s/\/\/.*$//mg; return $s }
sub pkgpath { my $f=shift; $f=~s/^\Q$ROOT\E\/?//; my $d=$f; $d=~s/\/[^\/]+$//; $d ? "github.com/usememos/memos/$d" : "github.com/usememos/memos" }

for my $f (@files) {
  open my $fh,'<',$f or next;
  my $raw=do{local $/;<$fh>}; close $fh;
  my $nc=strip($raw);
  my $pp=pkgpath($f);
  my @lines=split/\n/,$nc;
  for my $i (0..$#lines) {
    my $ln=$i+1; my $line=$lines[$i];
    if ($line =~ /^\s*func\s+(?:(\([^)]*\)\s+)?(\w+))\s*\(/) {
      my ($recv_raw,$name)=($1,$2);
      next if $name =~ /^(Test|Benchmark|Example|Fuzz)/;
      my $recv='';
      if (defined $recv_raw) {
        if ($recv_raw =~ /\*\s*(\w+)/) { $recv="*$1" }
        elsif ($recv_raw =~ /(\w+)/) { $recv=$1 }
      }
      push @{$sym{$name}}, {recv=>$recv, path=>$f, line=>$ln, pp=>$pp, name=>$name};
    }
  }
}

# Scan all repo for calls
my %all_go = map { $_=>1 } grep { /\.go$/ && $_!~/_test\.go$/ } `find $ROOT -name '*.go' ! -name '*_test.go'`;
chomp keys %all_go;

# fanin: sym_name -> {caller_file => count}
my %fanin_files;
my %fanin_sites;
my %fanin_detail;

for my $callfile (keys %all_go) {
  open my $fh,'<',$callfile or next;
  my $raw=do{local $/;<$fh>}; close $fh;
  my $nc=strip($raw);
  my @lines=split/\n/,$nc;
  for my $i (0..$#lines) {
    my $ln=$i+1; my $line=$lines[$i];
    if ($line =~ /^\s*func\s+/) { next }

    # For each symbol name, check if called on this line
    for my $name (keys %sym) {
      # qualified: something.name(
      while ($line =~ /(?<![\w.])\w+\.\Q$name\E\s*\(/g) {
        for my $def (@{$sym{$name}}) {
          if ($callfile eq $def->{path} && $ln == $def->{line}) { next }
          $fanin_files{"$def->{pp}|$def->{recv}|$name"}{$callfile}++;
          $fanin_sites{"$def->{pp}|$def->{recv}|$name"}++;
          $fanin_detail{"$def->{pp}|$def->{recv}|$name"}->{"$callfile:$ln"}=1;
        }
      }
      # receiver method: .name( but not definition
      while ($line =~ /(?<![\w])\.\Q$name\E\s*\(/g) {
        for my $def (@{$sym{$name}}) {
          if ($callfile eq $def->{path} && $ln == $def->{line}) { next }
          # only count as receiver call if it's a method (has recv)
          if ($def->{recv} ne '') {
            $fanin_files{"$def->{pp}|$def->{recv}|$name"}{$callfile}++;
            $fanin_sites{"$def->{pp}|$def->{recv}|$name"}++;
            $fanin_detail{"$def->{pp}|$def->{recv}|$name"}->{"$callfile:$ln"}=1;
          }
        }
      }
      # unqualified name( for package-level funcs
      if ($line =~ /(?<![\w.])\Q$name\E\s*\(/ && $callfile =~ /\/internal\//) {
        for my $def (@{$sym{$name}}) {
          if ($def->{recv} ne '') { next }
          if ($callfile eq $def->{path} && $ln == $def->{line}) { next }
          $fanin_files{"$def->{pp}|$def->{recv}|$name"}{$callfile}++;
          $fanin_sites{"$def->{pp}|$def->{recv}|$name"}++;
        }
      }
    }
  }
}

# Also scan unqualified from outside internal for exported funcs - same package won't apply
# qualified from outside already covered

my @ranked = sort {
  (scalar(keys%{$fanin_files{$b}})) <=> (scalar(keys%{$fanin_files{$a}}))
  || ($fanin_sites{$b} <=> $fanin_sites{$a})
} keys %fanin_files;

print "TOP 25 (caller_files, sites, symbol, path):\n";
for my $i (0..24) {
  last unless defined $ranked[$i];
  my $key=$ranked[$i];
  my ($pp,$recv,$name)=split/\|/,$key,3;
  my $symstr = $recv ? "$recv.$name" : $name;
  # find path
  my $path = $sym{$name}->[0]->{path};
  for my $d (@{$sym{$name}}) {
    if ("$d->{pp}|$d->{recv}|$d->{name}" eq $key) { $path=$d->{path}; last }
  }
  print scalar(keys%{$fanin_files{$key}}), "\t", $fanin_sites{$key}, "\t$symstr\t$path\n";
}

if (@ranked) {
  my $key=$ranked[0];
  print "\nDETAIL top:\n";
  for (sort keys %{$fanin_detail{$key}}) { print "  $_\n" }
}

