# Unique internal-only symbols: defined only in internal/, count qualified calls
perl -e '
use strict;
my $ROOT="/bench/repo";
# get all defs repo-wide: name -> count
my %defcount;
my @all = `find $ROOT -name "*.go" ! -name "*_test.go"`;
chomp @all;
for my $f (@all) {
  open F,"<",$f or next;
  while(<F>) {
    if (/^func (?:\([^)]*\)\s+)?(\w+)/) { $defcount{$1}++ }
  }
  close F;
}
# internal defs
for my $f (@all) {
  next unless $f =~ /\/internal\//;
  open F,"<",$f or next;
  while(<F>) {
    if (/^func (?:\([^)]*\)\s+)?(\w+)/) {
      my $n=$1;
      next if $n =~ /^(Test|Benchmark|Example)/;
      if ($defcount{$n} == 1) {
        # count qualified calls
        my $out = `grep -r --include="*.go" --exclude="*_test.go" -E "[^A-Za-z0-9_]\\w+\\.$n\\s*\\(" $ROOT 2>/dev/null | grep -vc "func "`;
        chomp $out;
        my $dot = `grep -r --include="*.go" --exclude="*_test.go" -E "\\.$n\\s*\\(" $ROOT 2>/dev/null | grep -vc "func "`;
        chomp $dot;
        my $total = $out + $dot;
        if ($total >= 5) print "$total qualified=$out dot=$dot $n $f\n";
      }
    }
  }
  close F;
}
' 2>&1

