perl -e '
use strict;
my $ROOT="/bench/repo";
my $MODULE="github.com/usememos/memos";

my @files = `find $ROOT -name "*.go" ! -name "*_test.go"`;
chomp @files;

sub strip { my $s=shift; $s=~s/\/\*.*?\*//gs; $s=~s/\/\/.*$//mg; return $s }
sub basename { my $p=shift; $p=~s{.*/}{}; return $p }
sub pkgpath { my $f=shift; $f=~s/^\Q$ROOT\E\/?//; my $d=$f; $d=~s/\/[^\/]+$//; ($d eq ""||$d eq $f) ? $MODULE : "$MODULE/$d" }

my %file_pkg; my %file_pp; my %imports; my %defs; my %ppname;
my %fanin_func; my %fanin_sites;

for my $f (@files) {
  open my $fh,"<",$f or next;
  my $raw=do{local $/;<$fh>}; close $fh;
  my $nc=strip($raw);
  my ($pkg)=$nc=~/^\s*package\s+(\w+)/m; $pkg//="main";
  my $pp=pkgpath($f);
  $file_pkg{$f}=$pkg; $file_pp{$f}=$pp;
  while ($nc=~/import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
    if (defined $1) {
      my $b=$1;
      while ($b=~/(?:(\w+)\s+)?"([^"]+)"/g) {
        my ($a,$imp)=($1,$2); $a=basename($imp) unless defined $a;
        if ($imp=~/\/internal\//) $imports{"$f|$a"}=$imp;
      }
    } else {
      my $imp=$2; my $a=basename($imp);
      if ($imp=~/\/internal\//) $imports{"$f|$a"}=$imp;
    }
  }
  my @lines=split/\n/,$nc;
  my @func_stack;
  for my $i (0..$#lines) {
    my $ln=$i+1; my $line=$lines[$i];
    if ($line=~/^\s*func\s+(?:(\([^)]*\)\s+)?(\w+))\s*\(/) {
      my ($recv_raw,$name)=($1,$2);
      my $recv=""; if (defined $recv_raw) {
        if ($recv_raw=~/\*\s*(\w+)/) $recv="*$1"; elsif ($recv_raw=~/(\w+)/) $recv=$1;
      }
      my $sym=$recv ? "$recv.$name" : $name;
      @func_stack=($sym); # simplified: only track current func
      $current_func{$f}=$sym;
      $func_start{$f}{$ln}=$sym;
      if ($f=~/\/internal\//) {
        my $key="$pp|$recv|$name";
        $defs{$key}={path=>$f,line=>$ln,recv=>$recv,name=>$name,pp=>$pp};
        push @{$ppname{"$pp|$name"}}, $key;
      }
      next;
    }
    if ($line=~/^\s*func\s+/) { next }
    my $caller="<top>";
    for my $start (sort {$a<=>$b} keys %{$func_start{$f}}) {
      if ($start <= $ln) { $caller=$func_start{$f}{$start} }
    }
    while ($line=~/(?<![\w.])(\w+)\.(\w+)\s*\(/g) {
      my ($alias,$fname)=($1,$2);
      my @targets;
      if (my $imp=$imports{"$f|$alias"}) push @targets,@{$ppname{"$imp|$fname"}//[]};
      if ($alias eq $pkg) push @targets,@{$ppname{"$pp|$fname"}//[]};
      for my $key (@targets) {
        my $d=$defs{$key}; next unless $d;
        if ($f eq $d->{path} && $ln==$d->{line}) next;
        $fanin_func{"$key|$f|$caller"}=1;
        $fanin_sites{$key}++;
      }
    }
    while ($line=~/(?<![\w.])(\w+)\s*\(/g) {
      my $fname=$1;
      next if $fname=~/^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|print|println|close|complex|real|imag|map|struct|interface|chan|range|case|default|select|else|const|var|type|import|package)$/;
      if ($f=~/\/internal\//) {
        for my $key (@{$ppname{"$pp|$fname"}//[]}) {
          my $d=$defs{$key}; next unless $d;
          if ($f eq $d->{path} && $ln==$d->{line}) next;
          $fanin_func{"$key|$f|$caller"}=1;
          $fanin_sites{$key}++;
        }
      }
    }
  }
}

my %callers;
for my $k (keys %fanin_func) {
  my ($key,$f,$caller)=split/\|/,$k,3;
  $callers{$key}++;
}
my @ranked=sort { $callers{$b}<=>$callers{$a} || $fanin_sites{$b}<=>$fanin_sites{$a} } keys %callers;
print "TOP 15 by distinct caller functions:\n";
for my $i (0..14) {
  last unless defined $ranked[$i];
  my $key=$ranked[$i];
  my $d=$defs{$key};
  my $sym=$d->{recv} ? "$d->{recv}.$d->{name}" : $d->{name};
  print "$callers{$key} funcs, $fanin_sites{$key} sites, $sym, $d->{path}\n";
}
' 2>&1

